<template><nav class="care-progress" aria-label="一天照護故事進度"><ol><li v-for="(item,index) in items" :key="item.id" :class="{'is-active':index===active}"><a :href="`#care-scene-${item.id}`" :aria-label="`第 ${item.id} 幕`" :aria-current="index===active?'step':undefined"><span>{{ item.id }}</span><i aria-hidden="true"></i></a></li></ol><p aria-live="polite">{{ current?.id }} / 08</p></nav></template>
<script setup lang="ts">import{computed}from'vue';const props=defineProps<{items:{id:string}[];active:number}>();const current=computed(()=>props.items[props.active]);</script>
<style scoped>.care-progress{position:fixed;z-index:20;right:12px;top:50%;transform:translateY(-50%)}ol{display:grid;gap:8px;margin:0;padding:10px;list-style:none}a{display:flex;align-items:center;gap:7px;color:#fff;text-decoration:none;font-size:.65rem;opacity:.3;transition:opacity .2s ease}i{width:7px;height:7px;background:#fff;border-radius:50%;transform:scale(.6);transition:transform .2s ease}.is-active a{opacity:1}.is-active i{transform:scale(1)}p{display:none}@media(max-width:900px){.care-progress{top:auto;right:12px;bottom:12px;transform:none}ol{display:none}p{display:block;margin:0;padding:8px 11px;color:#fff;background:#2d2019cc;border-radius:999px;font-size:.78rem;font-weight:700}}</style>
